import json
d = json.load(open('/tmp/ixp_node_full.json'))
node = d['Data']['Node']
out = node.get('outputDefinition',{}).get('output',{})
schema = out.get('schema',{})
# find Tables definition
def find_key(obj, key, path=''):
    results = []
    if isinstance(obj, dict):
        for k,v in obj.items():
            if k == key:
                results.append((path+'/'+k, v))
            results.extend(find_key(v, key, path+'/'+k))
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            results.extend(find_key(v, key, path+f'[{i}]'))
    return results
res = find_key(schema, 'Tables')
for p, v in res[:3]:
    print(p)
    print(json.dumps(v, indent=2)[:2000])
"

